97	export default function App() {
98	  const { apiKey, chatwootToken } = useLoaderData<typeof loader>();
99	
100	  return (
101	    <AppProvider embedded apiKey={apiKey}>
102	      <PolarisAppProvider i18n={enTranslations}>
103	        <ChatwootWidget token={chatwootToken} />
104	        <NavMenu>
105	          <a href="/app/zip-codes">Zip Codes</a>
106	          <a href="/app/delivery-rules">Delivery Rules</a>
107	          <a href="/app/waitlist">Waitlist</a>
108	          <a href="/app/widget">Widget Customization</a>
109	          <a href="/app/settings">Settings</a>
110	          <a href="/app/help">Help &amp; Support</a>
111	        </NavMenu>
112	        <AppContent />
113	      </PolarisAppProvider>
114	    </AppProvider>
115	  );
116	}
