186	    try {
187	      return localStorage.getItem("zcc-onboarding-dismissed") === "true";
188	    } catch {
189	      return false;
190	    }
191	  });
192	  const handleDismissOnboarding = useCallback(() => {
193	    setOnboardingDismissed(true);
194	    try {
195	      localStorage.setItem("zcc-onboarding-dismissed", "true");
196	    } catch {
197	      // localStorage unavailable in some contexts
198	    }
199	  }, []);
200	  const isFreePlan = subscription.planTier === "free";
201	  const hasZipLimit = limits.maxZipCodes < UNLIMITED;
202	  const isEmpty = stats.total === 0;
203	
204	  const usagePercent =
205	    limits.maxZipCodes < UNLIMITED
