208	
209	  const planLabel = limits.label;
210	
211	  return (
212	    <Page
213	      title="Dashboard"
214	      subtitle={`${planLabel} Plan`}
215	      primaryAction={{
216	        content: "Add Zip Code",
217	        icon: PlusIcon,
218	        onAction: () => navigate("/app/zip-codes"),
219	      }}
220	    >
221	      <Box paddingBlockEnd="1600">
222	        <BlockStack gap="500">
223	
224	          {/* ─── 1. APP STATUS ─── */}
225	          {appEmbedEnabled ? (
226	            <Banner
227	              tone="success"
228	              title="Widget is live on your store"
229	              action={{
230	                content: "Open Theme Editor",
231	                url: themeEditorUrl,
232	                external: true,
233	              }}
234	            >
235	              <Text as="p" variant="bodySm">
236	                {activeThemeName
237	                  ? `Running on your ${activeThemeName} theme. `
238	                  : ""}
239	                Any changes you make here apply to your storefront instantly.
240	              </Text>
241	            </Banner>
242	          ) : (
243	            <Banner
244	              tone="warning"
245	              title="2 steps to show the widget on your store"
246	              action={{
247	                content: "Enable in Theme Editor",
248	                url: themeEditorAppEmbedsUrl,
249	                external: true,
250	              }}
251	              secondaryAction={{
252	                content: revalidateState === "loading" ? "Checking..." : "Refresh status",
253	                onAction: revalidate,
254	              }}
255	            >
256	              <List type="number">
257	                <List.Item>
258	                  Open <strong>Theme Editor &gt; App Embeds</strong> and turn on{" "}
259	                  <strong>Pinzo</strong>
260	                </List.Item>
261	                <List.Item>
262	                  Go to your <strong>Product template</strong>, add the{" "}
263	                  <strong>Pinzo</strong> block, and save
264	                </List.Item>
265	              </List>
266	            </Banner>
267	          )}
268	
269	          {/* ─── 2. STATS ─── */}
270	          {!isEmpty && (
271	            <Card>
272	              <BlockStack gap="400">
273	                <InlineGrid columns={{ xs: 2, sm: 3, md: 5 }} gap="400">
274	                  <BlockStack gap="100">
275	                    <Text as="p" variant="headingXl" fontWeight="bold">
276	                      {stats.total}
277	                      {limits.maxZipCodes < UNLIMITED && (
278	                        <Text as="span" variant="bodySm" tone="subdued" fontWeight="regular">
279	                          {" "}/ {limits.maxZipCodes}
280	                        </Text>
281	                      )}
282	                    </Text>
283	                    <Text as="p" variant="bodySm" tone="subdued">
284	                      Zip codes
285	                    </Text>
286	                  </BlockStack>
287	
288	                  <BlockStack gap="100">
289	                    <Text as="p" variant="headingXl" fontWeight="bold" tone="success">
290	                      {stats.allowed}
291	                    </Text>
292	                    <Text as="p" variant="bodySm" tone="subdued">
293	                      Serviceable
294	                    </Text>
295	                  </BlockStack>
296	
297	                  <BlockStack gap="100">
298	                    <Text as="p" variant="headingXl" fontWeight="bold" tone={stats.blocked > 0 ? "critical" : "subdued"}>
299	                      {stats.blocked}
300	                    </Text>
301	                    <Text as="p" variant="bodySm" tone="subdued">
302	                      Blocked
303	                    </Text>
304	                  </BlockStack>
305	
306	                  <BlockStack gap="100">
307	                    <Text as="p" variant="headingXl" fontWeight="bold" tone={stats.waitlist > 0 ? "caution" : "subdued"}>
308	                      {stats.waitlist}
309	                    </Text>
310	                    <Text as="p" variant="bodySm" tone="subdued">
311	                      Waitlisted
312	                    </Text>
313	                  </BlockStack>
314	
315	                  <BlockStack gap="100">
316	                    <Text as="p" variant="headingXl" fontWeight="bold">
317	                      {stats.deliveryRules}
318	                    </Text>
319	                    <Text as="p" variant="bodySm" tone="subdued">
320	                      Delivery rules
321	                    </Text>
322	                  </BlockStack>
323	                </InlineGrid>
324	
325	                {/* Usage bar — shown when plan has a finite zip limit */}
326	                {hasZipLimit && (
327	                  <>
328	                    <Divider />
329	                    <BlockStack gap="200">
330	                      <InlineStack align="space-between">
