# The interactive div must stay as a div since Polaris Box doesn't support
# onClick, onKeyDown, role="button", or tabIndex. However, we wrap with Box
# for the outer key container, and use Polaris design token vars for the 
# background color. This is the minimal-footprint compromise that's
# necessary because Polaris has no clickable container component.
new_block = '''              {faqs.map((faq, index) => (
                <Box key={faq.question}>
                  {/* Interactive accordion trigger — Polaris has no clickable container
                      component, so a minimal div with role="button" is required here.
                      Background uses Polaris design tokens. */}
                  <div
                    role="button"
                    tabIndex={0}
                    onClick={() => handleFaqToggle(index)}
                    onKeyDown={(e) => {
                      if (e.key === "Enter" || e.key === " ") {
                        e.preventDefault();
                        handleFaqToggle(index);
                      }
                    }}
                    style={{
                      cursor: "pointer",
                      padding: "var(--p-space-400)",
                      background:
                        openFaq === index
                          ? "var(--p-color-bg-surface-hover)"
                          : "transparent",
                      transition: "background 150ms ease",
                    }}
                  >
                    <InlineStack align="space-between" blockAlign="center">
                      <Text as="p" variant="bodyMd" fontWeight="semibold">
                        {faq.question}
                      </Text>
                      <Box>
                        <Icon
                          source={
                            openFaq === index
                              ? ChevronUpIcon
                              : ChevronDownIcon
                          }
                          tone="subdued"
                        />
                      </Box>
                    </InlineStack>
                  </div>
                  <Collapsible
                    open={openFaq === index}
                    id={`faq-${index}`}
                    transition={{
                      duration: "200ms",
                      timingFunction: "ease-in-out",
                    }}
                  >
                    <Box
                      padding="400"
                      paddingBlockStart="0"
                      background="bg-surface-hover"
                    >
                      <Text as="p" tone="subdued" variant="bodyMd">
                        {faq.answer}
                      </Text>
                    </Box>
                  </Collapsible>
                  {index < faqs.length - 1 && <Divider />}
                </Box>
              ))}'''

content = content.replace(old_block, new_block)

with open('app/routes/app.help.tsx', 'w') as f:
    f.write(content)

print("Fixed app.help.tsx - reverted to working hybrid approach")
